import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(s.firstMissingPositive(new int[]{1,2,0})!=3||s.firstMissingPositive(new int[]{3,4,-1,1})!=2||s.firstMissingPositive(new int[]{7,8,9,11,12})!=1||s.firstMissingPositive(new int[]{Integer.MIN_VALUE,Integer.MAX_VALUE})!=1)throw new AssertionError();Random r=new Random(11);for(int t=0;t<3000;t++){int n=1+r.nextInt(60);int[] a=new int[n];Set<Integer> v=new HashSet<>();for(int i=0;i<n;i++){a[i]=r.nextInt(100)-25;v.add(a[i]);}int w=1;while(v.contains(w))w++;if(s.firstMissingPositive(a)!=w)throw new AssertionError();}int[] a=new int[100000];Arrays.fill(a,1);if(s.firstMissingPositive(a)!=2)throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}}